function useSessionStorage<T>(key: string, initial: T) {
  const [value, setValue] = useState<T>(() => {
    try { return JSON.parse(sessionStorage.getItem(key) || '') as T } catch { return initial }
  })
  const update = (next: T | ((current: T) => T)) => {
    setValue((current) => {
      const result = typeof next === 'function' ? (next as (current: T) => T)(current) : next
      sessionStorage.setItem(key, JSON.stringify(result))
      return result
    })
  }
  return [value, update] as const
}

function App() {
  const navigate = useNavigate()
  const [wishlist, setWishlist] = useSessionStorage<{ kind: WishlistKind; id: string }[]>('wandor-wishlist', [])
  const [userTrips, setUserTrips] = useSessionStorage('wandor-trips', seedTrips)
  const [chatOpen, setChatOpen] = useState(false)
  const [notice, setNotice] = useState('')
  const [booking, setBooking] = useState({ id: 'WAN12345678', total: 58499, trip: 'Bengaluru → Tokyo', date: '12 October 2026' })
  const toggleWish = (kind: WishlistKind, id: string) => {
    setWishlist((current) => current.some((item) => item.kind === kind && item.id === id) ? current.filter((item) => !(item.kind === kind && item.id === id)) : [...current, { kind, id }])
    setNotice('Wishlist updated')
    window.setTimeout(() => setNotice(''), 1800)
  }
  const isWished = (kind: WishlistKind, id: string) => wishlist.some((item) => item.kind === kind && item.id === id)
  const createBooking = (total: number, trip: string) => {
    const id = `WAN${Math.floor(10000000 + Math.random() * 89999999)}`
    const next = { id, total, trip, date: '12 October 2026' }
    setBooking(next)
    setUserTrips((current) => [{ id, destination: trip, dates: '12–19 October 2026', type: 'Simulated booking', status: 'Upcoming', amount: total }, ...current])
    navigate('/confirmation')
  }
  return (
    <div className="min-h-screen bg-white text-wandor-text">
      <AppShell wishlistCount={wishlist.length} onChat={() => setChatOpen(true)} />
      {notice && <div className="fixed left-1/2 top-5 z-[70] -translate-x-1/2 rounded-full bg-wandor-dark px-5 py-3 text-xs font-semibold text-white shadow-xl">{notice}</div>}
      <Routes>
        <Route path="/" element={<HomePage onPlan={() => navigate('/planner')} onSearch={(mode, query) => navigate(`/search?mode=${mode}&q=${encodeURIComponent(query)}`)} isWished={isWished} toggleWish={toggleWish} />} />
        <Route path="/search" element={<SearchPage isWished={isWished} toggleWish={toggleWish} />} />
        <Route path="/planner" element={<PlannerPage onBook={() => navigate('/search?mode=hotels')} />} />
        <Route path="/hotel/:id" element={<HotelPage onReserve={(hotel) => navigate(`/checkout?type=hotel&id=${hotel.id}`)} isWished={isWished} toggleWish={toggleWish} />} />
        <Route path="/trips" element={<TripsPage trips={userTrips} />} />
        <Route path="/wishlist" element={<WishlistPage wishlist={wishlist} isWished={isWished} toggleWish={toggleWish} />} />
        <Route path="/guides" element={<GuidesPage />} />
        <Route path="/checkout" element={<CheckoutPage onConfirm={createBooking} />} />
        <Route path="/confirmation" element={<ConfirmationPage booking={booking} />} />
        <Route path="/admin" element={<AdminPage />} />
        <Route path="*" element={<HomePage onPlan={() => navigate('/planner')} onSearch={(mode, query) => navigate(`/search?mode=${mode}&q=${encodeURIComponent(query)}`)} isWished={isWished} toggleWish={toggleWish} />} />
      </Routes>
      <MobileNav wishlistCount={wishlist.length} />
      <WandorChat open={chatOpen} onClose={() => setChatOpen(false)} onOpen={() => setChatOpen(true)} />
    </div>
  )
}

