            <button onClick={() => setMenuOpen((open) => !open)} className="rounded-full border border-black/10 bg-white/45 p-2.5 text-wandor-dark backdrop-blur lg:hidden" aria-label={menuOpen ? 'Close menu' : 'Open menu'}><Menu size={18} /></button>
